function camelToSnake(str) {
  if (typeof str !== 'string') {
    throw new TypeError('Argument must be a string');
  }

  // Insert underscore between a lower-case letter or digit and a following upper-case letter
  let result = str.replace(/([a-z0-9])([A-Z])/g, '$1_$2');

  // Insert underscore between an upper-case letter and a following upper-case letter
  // that is itself followed by a lower-case letter (end of an acronym)
  result = result.replace(/([A-Z]+)([A-Z][a-z])/g, '$1_$2');

  return result.toLowerCase();
}

module.exports = { camelToSnake };
