function parseQuery(qs) {
  if (typeof qs !== 'string') {
    throw new TypeError('qs must be a string');
  }

  // Remove leading '?' if present
  if (qs.startsWith('?')) {
    qs = qs.slice(1);
  }

  if (qs === '') {
    return {};
  }

  const result = Object.create(null);
  const pairs = qs.split('&');

  for (const pair of pairs) {
    if (pair === '') {
      continue;
    }

    const eqIndex = pair.indexOf('=');
    let key, value;

    if (eqIndex === -1) {
      key = pair;
      value = '';
    } else {
      key = pair.slice(0, eqIndex);
      value = pair.slice(eqIndex + 1);
    }

    // Decode key and value
    const decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));
    const decodedValue = decodeURIComponent(value.replace(/\+/g, ' '));

    if (decodedKey === '') {
      continue;
    }

    if (result.hasOwnProperty(decodedKey)) {
      if (Array.isArray(result[decodedKey])) {
        result[decodedKey].push(decodedValue);
      } else {
        result[decodedKey] = [result[decodedKey], decodedValue];
      }
    } else {
      result[decodedKey] = decodedValue;
    }
  }

  return result;
}

module.exports = { parseQuery };
