function topoSort(graph) {
  // Collect all tasks (keys and values in dependency lists)
  const allTasks = new Set();
  const inDegree = new Map();
  const adj = new Map(); // task -> list of tasks that depend on it

  // Initialize from keys
  for (const task of Object.keys(graph)) {
    allTasks.add(task);
    inDegree.set(task, 0);
    adj.set(task, []);
  }

  // Process dependencies
  for (const [task, deps] of Object.entries(graph)) {
    const uniqueDeps = [...new Set(deps)];
    for (const dep of uniqueDeps) {
      allTasks.add(dep);
      if (!inDegree.has(dep)) {
        inDegree.set(dep, 0);
        adj.set(dep, []);
      }
      // dep must come before task, so task depends on dep
      // This means in the graph for Kahn's: edge from dep -> task
      adj.get(dep).push(task);
      inDegree.set(task, inDegree.get(task) + 1);
    }
  }

  // Initialize queue with tasks having no dependencies
  const queue = [];
  for (const task of allTasks) {
    if (inDegree.get(task) === 0) {
      queue.push(task);
    }
  }

  // Sort queue to ensure we pick smallest name first
  queue.sort();

  const result = [];
  const processedCount = 0;

  while (queue.length > 0) {
    // Pick the smallest task
    queue.sort();
    const current = queue.shift();
    result.push(current);

    // Process neighbors
    const neighbors = adj.get(current) || [];
    for (const neighbor of neighbors) {
      inDegree.set(neighbor, inDegree.get(neighbor) - 1);
      if (inDegree.get(neighbor) === 0) {
        queue.push(neighbor);
      }
    }
  }

  // Check for cycle
  if (result.length !== allTasks.size) {
    throw new Error('cycle detected');
  }

  return result;
}

module.exports = { topoSort };
