function deepEqual(a, b) {
  // Handle primitives and special cases
  if (a === b) {
    // This covers most primitives, null, and same object/function references
    // But we need to handle NaN separately since NaN !== NaN
    if (Number.isNaN(a) && Number.isNaN(b)) {
      return true;
    }
    return true;
  }

  // If one is NaN and the other isn't, they are not equal
  if (Number.isNaN(a) || Number.isNaN(b)) {
    return false;
  }

  // Handle null explicitly (though === usually catches it, being safe)
  if (a === null || b === null) {
    return a === b;
  }

  // Handle functions: must be the same reference
  if (typeof a === 'function' || typeof b === 'function') {
    return a === b;
  }

  // Handle Dates
  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime();
  }
  if (a instanceof Date || b instanceof Date) {
    return false;
  }

  // Handle Arrays
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) {
      return false;
    }
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) {
        return false;
      }
    }
    return true;
  }
  if (Array.isArray(a) || Array.isArray(b)) {
    return false;
  }

  // Handle Plain Objects
  if (typeof a === 'object' && typeof b === 'object') {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);

    if (keysA.length !== keysB.length) {
      return false;
    }

    for (const key of keysA) {
      if (!Object.prototype.hasOwnProperty.call(b, key)) {
        return false;
      }
      if (!deepEqual(a[key], b[key])) {
        return false;
      }
    }

    return true;
  }

  // Fallback for any other types (should be covered by earlier checks)
  return false;
}

module.exports = { deepEqual };
