function formatBytes(n) {
  if (typeof n !== 'number' || !Number.isFinite(n)) {
    throw new TypeError('n must be a finite number');
  }
  if (n < 0 || !Number.isInteger(n)) {
    throw new RangeError('n must be a non-negative integer');
  }

  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let value = n;
  let unitIndex = 0;

  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex++;
  }

  // Round to at most one decimal place
  let formattedValue;
  if (Number.isInteger(value)) {
    formattedValue = value;
  } else {
    formattedValue = Math.round(value * 10) / 10;
  }

  // Check if rounding pushed us to 1024 and we can move up
  if (formattedValue === 1024 && unitIndex < units.length - 1) {
    formattedValue = 1;
    unitIndex++;
  }

  // Format the number: remove .0 if present
  let valueStr;
  if (Number.isInteger(formattedValue)) {
    valueStr = String(formattedValue);
  } else {
    valueStr = formattedValue.toFixed(1);
  }

  return `${valueStr} ${units[unitIndex]}`;
}

module.exports = { formatBytes };
