function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const trimmed = spec.trim();
  if (trimmed === '') {
    return [];
  }

  const parts = trimmed.split(',');
  const result = new Set();

  for (const part of parts) {
    if (part === '') {
      throw new SyntaxError('Empty part detected');
    }

    const dashIndex = part.indexOf('-');

    if (dashIndex === -1) {
      // Single number
      if (!/^\d+$/.test(part)) {
        throw new SyntaxError('Invalid number format');
      }
      const num = parseInt(part, 10);
      result.add(num);
    } else {
      // Range
      if (part.indexOf('-', dashIndex + 1) !== -1) {
        throw new SyntaxError('More than one dash in part');
      }

      const loStr = part.slice(0, dashIndex);
      const hiStr = part.slice(dashIndex + 1);

      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('Missing start or end in range');
      }

      if (!/^\d+$/.test(loStr) || !/^\d+$/.test(hiStr)) {
        throw new SyntaxError('Invalid number format in range');
      }

      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);

      if (lo > hi) {
        throw new RangeError('Range start must not exceed end');
      }

      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

