import re

def rle_encode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    if any(c.isdigit() for c in s):
        raise ValueError("Input string must not contain digit characters")

    if not s:
        return ""

    result = []
    current_char = s[0]
    count = 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{count}{current_char}")
            current_char = char
            count = 1

    result.append(f"{count}{current_char}")
    return "".join(result)

def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    if not s:
        return ""

    # Pattern to match one or more digits followed by a non-digit character
    pattern = r'(\d+)(\D)'
    matches = re.findall(pattern, s)

    # Check if the entire string matches the pattern
    if not matches:
        raise ValueError("Invalid RLE string: no valid count-character pairs found")

    # Reconstruct the string from matches to verify full coverage
    reconstructed = "".join(f"{count}{char}" for count, char in matches)
    if reconstructed != s:
        raise ValueError("Invalid RLE string: trailing digits or missing character")

    result = []
    for count_str, char in matches:
        count = int(count_str)
        if count == 0:
            raise ValueError("Count must be at least 1")
        result.append(char * count)

    return "".join(result)
