  if (typeof dateStr !== 'string') {
    throw new TypeError('dateStr must be a string');
  }
  if (!Number.isInteger(days)) {
    throw new TypeError('days must be an integer');
  }

  const regex = /^(\d{4})-(\d{2})-(\d{2})$/;
  const match = dateStr.match(regex);
  if (!match) {
    throw new RangeError('dateStr has the wrong shape');
  }

  const year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const day = parseInt(match[3], 10);

  if (year < 1 || year > 9999) {
    throw new RangeError('year must be between 0001 and 9999');
  }

  // Validate the date using UTC to avoid DST issues
  const utcDate = new Date(Date.UTC(year, month - 1, day));
  if (
    utcDate.getUTCFullYear() !== year ||
    utcDate.getUTCMonth() !== month - 1 ||
    utcDate.getUTCDate() !== day
  ) {
    throw new RangeError('dateStr is not a real calendar date');
  }

  // Add days
  const newDate = new Date(utcDate);
  newDate.setUTCDate(newDate.getUTCDate() + days);

  const newYear = newDate.getUTCFullYear();
  const newMonth = newDate.getUTCMonth() + 1;
  const newDay = newDate.getUTCDate();

  if (newYear < 1 || newYear > 9999) {
    throw new RangeError('result year must be between 0001 and 9999');
  }

  const pad = (n) => String(n).padStart(2, '0');
  const padYear = (n) => String(n).padStart(4, '0');

  return `${padYear(newYear)}-${pad(newMonth)}-${pad(newDay)}`;
}

module.exports = { addDays };

