  const memoized = function (...args) {
    let key;
    if (keyFn) {
      key = keyFn.apply(this, args);
    } else {
      key = args[0];
    }

    if (cache.has(key)) {
      return cache.get(key);
    }

    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  };

  memoized.clear = function () {
    cache.clear();
  };

  return memoized;
}

