  // Calculate column widths
  for (let i = 0; i < rows.length; i++) {
    for (let j = 0; j < rows[i].length; j++) {
      const cell = rows[i][j] == null ? '' : String(rows[i][j]);
      if (cell.length > colWidths[j]) {
