  const firstStr = strs[0];
  const firstCodePoints = [...firstStr];

  let prefixLength = 0;

  // Iterate through each code point of the first string
  for (let i = 0; i < firstCodePoints.length; i++) {
    const char = firstCodePoints[i];

    // Check if this character exists at the same position in all other strings
    for (let j = 1; j < strs.length; j++) {
      const otherStr = strs[j];
      const otherCodePoints = [...otherStr];

      if (i >= otherCodePoints.length || otherCodePoints[i] !== char) {
        return firstStr.slice(0, prefixLength);
      }
    }

    prefixLength++;
  }

  return firstStr.slice(0, prefixLength);
