function createLimiter({ capacity, refillPerSec, now }) {
  if (typeof now !== 'function') {
    throw new TypeError('now must be a function');
  }
  if (!Number.isInteger(capacity) || capacity <= 0) {
    throw new RangeError('capacity must be a positive integer');
  }
  if (!Number.isFinite(refillPerSec) || refillPerSec <= 0) {
    throw new RangeError('refillPerSec must be a positive finite number');
  }

  let tokens = capacity;
  let lastTime = now();

  function tryTake(n = 1) {
    if (!Number.isInteger(n) || n <= 0) {
      throw new RangeError('n must be a positive integer');
    }

    const currentTime = now();
    const elapsedSeconds = (currentTime - lastTime) / 1000;

    if (elapsedSeconds > 0) {
      tokens = Math.min(capacity, tokens + elapsedSeconds * refillPerSec);
      lastTime = currentTime;
    }

    if (tokens >= n) {
      tokens -= n;
      return true;
    }

    return false;
  }

  return { tryTake };
}

module.exports = { createLimiter };
